    valueKey: {
        "Name": "DisplayName"
    },
    type: {
        "ProcessDate": "date",
        "PostingDate": "date",
        "DebitDate": "date",
        "TotalEmployees": "number"

        // "TotalGrossPay": "currency",
        // "TotalNetPay": "currency",
